const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const clock=document.querySelector('.clock');function tick(){clock.textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date())+' IST'}tick();setInterval(tick,1000);const links=[...document.querySelectorAll('.hdr nav a')],sections=[...document.querySelectorAll('main>section[id]')];const navIO=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)links.forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}),{rootMargin:'-40% 0px -55%'});sections.forEach(s=>navIO.observe(s));const revealIO=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');revealIO.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(x=>revealIO.observe(x));const cards=[...document.querySelectorAll('.work-card')],caption=document.querySelector('.work-caption'),count=document.querySelector('.work-count strong');let active=0;const names=['VANDANA TRAVELS — WEB DESIGN','INNOVEXA — STOREFRONT','OUT THERE — EXPERIENCE','DIGITAL SYSTEMS - CONCEPT STUDY','FORM STUDY — CONCEPT','BEYOND THE GRID — CONCEPT'];function arrange(){const mobile=innerWidth<800,step=mobile?16:22,base=50,drop=mobile?14:18,lift=mobile?8:0,ry=mobile?6:8;cards.forEach((c,i)=>{let d=i-active;c.style.transform=`translateX(${d*step-base}%) translateY(${Math.abs(d)*drop+lift}px) rotateY(${d*-ry}deg) rotate(${d*1.8}deg)`;c.style.zIndex=10-Math.abs(d);c.style.opacity=d===0?1:Math.max(.12,.68-Math.abs(d)*.24)});count.textContent=String(active+1).padStart(2,'0');caption.textContent=names[active]}arrange();addEventListener('resize',arrange);window.setWorkActive=index=>{active=Math.max(0,Math.min(cards.length-1,index));arrange()};document.querySelector('.work-stage').addEventListener('click',e=>{const c=e.target.closest('.work-card');if(c){active=cards.indexOf(c);arrange()}});document.querySelector('.work-stage').addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();active=(active+1)%cards.length}if(e.key==='ArrowLeft'){e.preventDefault();active=(active-1+cards.length)%cards.length}arrange()});const can=document.querySelector('#sigCanvas'),cx=can.getContext('2d');function size(){let d=Math.min(devicePixelRatio,2),r=can.getBoundingClientRect();can.width=r.width*d;can.height=r.height*d;cx.setTransform(d,0,0,d,0,0)}function field(t=0){let w=can.clientWidth,h=can.clientHeight;cx.clearRect(0,0,w,h);for(let i=0;i<90;i++){let a=i*.55+t*.00015,r=80+i*4.8,x=w/2+Math.cos(a)*r*1.7,y=h/2+Math.sin(a)*r*.58;cx.beginPath();cx.arc(x,y,1+(i%4),0,7);cx.fillStyle=`hsla(${245+i*.7},85%,65%,${.12+(i%5)*.035})`;cx.fill()}if(!reduce)requestAnimationFrame(field)}size();field();addEventListener('resize',size);if(!reduce)addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;document.querySelector('.collage').style.translate=`${(e.clientX/innerWidth-.5)*10}px ${(e.clientY/innerHeight-.5)*8}px`},{passive:true});
// FAQ accordion — close siblings when a details is opened
document.querySelectorAll('.faq details').forEach(d=>{d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('.faq details').forEach(s=>{if(s!==d)s.removeAttribute('open')})})});

